static inline bool xi_lowering_is_patterned(uint16_t op) {
    return xi_lowering_template_kind(op) != XI_LOWER_TEMPLATE_CUSTOM;
}

static inline bool xi_lowering_has_target(uint16_t op, uint32_t target) {
    return (xi_lowering_generated_targets(op) & target) == target;
}

static inline bool xi_lowering_target_is_rejected(uint16_t op, uint32_t target) {
    return (xi_lowering_rejected_targets(op) & target) == target;
}

